from itertools import permutations

class Solution:
    def minimumSum(self, num: int) -> int:
        best = float('inf')
        digits = str(num)
        for p in permutations(digits):
            for cut in range(1, 4):
                best = min(best, int(''.join(p[:cut])) + int(''.join(p[cut:])))
        return best

