class Solution {
    int best = Integer.MAX_VALUE;
    public int minimumSum(int num) {
        perm(String.valueOf(num).toCharArray(), 0);
        return best;
    }
    void perm(char[] c, int i) {
        if (i == c.length) {
            for (int cut = 1; cut < 4; cut++)
                best = Math.min(best,
                        Integer.parseInt(new String(c, 0, cut)) + Integer.parseInt(new String(c, cut, 4 - cut)));
            return;
        }
        for (int j = i; j < c.length; j++) {
            char t = c[i]; c[i] = c[j]; c[j] = t;
            perm(c, i + 1);
            t = c[i]; c[i] = c[j]; c[j] = t;
        }
    }
};

