var minimumSum = function(num) {
    let best = Infinity;
    const s = String(num).split('');
    const perm = i => {
        if (i === s.length) {
            for (let cut = 1; cut < 4; cut++)
                best = Math.min(best,
                    Number(s.slice(0, cut).join('')) + Number(s.slice(cut).join('')));
            return;
        }
        for (let j = i; j < s.length; j++) {
            [s[i], s[j]] = [s[j], s[i]];
            perm(i + 1);
            [s[i], s[j]] = [s[j], s[i]];
        }
    };
    perm(0);
    return best;
};

